def quantity(value, *, step=1):
    if type(value) is not int or type(step) is not int:
        raise TypeError("value and step must be exact integers")
    if not 1 <= step <= 5:
        raise ValueError("step out of range")
    if not 1 <= value <= 20 or value % step != 0:
        raise ValueError("quantity out of range or not aligned to step")
    return value

