import sys
sys.path.insert(0, "/workspace")
from quantity import quantity
assert quantity(3) == 3
assert quantity(20, step=5) == 20
for bad in (True, False, 1.5, "2", None):
    try:
        quantity(bad)
    except TypeError:
        pass
    else:
        raise AssertionError(f"accepted invalid quantity type: {bad!r}")
for bad_step in (True, False, 1.0, "1", None):
    try:
        quantity(4, step=bad_step)
    except TypeError:
        pass
    else:
        raise AssertionError(f"accepted invalid step type: {bad_step!r}")
for bad_args in ((0, 1), (21, 1), (4, 0), (4, 6), (7, 2)):
    try:
        quantity(bad_args[0], step=bad_args[1])
    except ValueError:
        pass
    else:
        raise AssertionError(f"accepted out-of-range or misaligned quantity: {bad_args!r}")
